#include <iostream>

class Money {
    long cents_;
public:
    Money(long c) : cents_(c) {}
    friend std::ostream& operator<<(std::ostream& os, const Money& m) {
        return os << m.cents_ / 100 << '.' << (m.cents_ % 100);
    }
};

int main() {
    Money m(1234);
    std::cout << m;      // 返回 ostream& 才能继续链式输出
}
